//////
///
/// $INTERFACE FigoINS                                  (4,4)
///     ###
///     * Instruction properties
///     ###
///     # # ----------------------------------------------------------
///     @ 0x00000 Mask                 (P)
///               %unsigned 24 INS
///               %%        8          # Stuffing bits...
///     @ 0x00004 Opcode               (P)
///               %unsigned 24 INS
///                                    ###
///                                    * To match instruction
///                                    ###
///               %%        8          # Stuffing bits...
///     @ 0x00008 ID                   (P)
///               ###
///               * Controls at ID stage
///               ###
///               %unsigned 1  RBRF
///                                    ###
///                                    * RB = RF16[ S4 ]
///                                    ###
///               %unsigned 1  RARF
///                                    ###
///                                    * RA = RF16[ S4 ]
///                                    ###
///               %unsigned 1  RAK8
///                                    ###
///                                    * RA = RB[15:0] + { 8{K8[7]}, K8[7:0] }
///                                    ###
///               %unsigned 1  RAI16
///                                    ###
///                                    * RA = I16 ( INS[19:4] )
///                                    ###
///               %unsigned 1  RAK16
///                                    ###
///                                    * RA = K16 ( { INS[19:8], INS[3:0] } )
///                                    ###
///               %unsigned 1  RFSP
///                                    ###
///                                    * RFSP = RF16[ S4 ]
///                                    ###
///               %unsigned 1  W4D4
///                                    ###
///                                    * W4 = D4[3:0]
///                                    ###
///               %unsigned 1  W4S4
///                                    ###
///                                    * W4 = S4[3:0]
///                                    ###
///               %%        24         # Stuffing bits...
///     @ 0x0000C LD                   (P)
///               ###
///               * Controls at LD stage
///               ###
///               %unsigned 1  SPRF
///                                    ###
///                                    * SP = RFSP[15:0]
///                                    ###
///               %unsigned 1  SPK8
///                                    ###
///                                    * SP = RFSP[15:0] + { 8{K8[7]}, K8[7:0] }
///                                    ###
///               %unsigned 1  SPJ
///                                    ###
///                                    * SP = PC[15:0] + { 8{H8[7]}, H8[7:0] }
///                                    ###
///               %unsigned 1  SP4S
///                                    ###
///                                    * SP = { 12{S4[3]}, S4[3:0] }
///                                    ###
///               %unsigned 1  SP8S
///                                    ###
///                                    * SP = { 8{H8[7]}, H8[7:0] }
///                                    ###
///               %unsigned 1  SP8U
///                                    ###
///                                    * SP = { 8'h00, H8[7:0] }
///                                    ###
///               %unsigned 1  SP12S
///                                    ###
///                                    * SP = { 4{I12[11]}, I12[11:0] }
///                                    ###
///               %unsigned 1  SP16
///                                    ###
///                                    * SP = I16[15:0]
///                                    ###
///               %unsigned 1  TPRF
///                                    ###
///                                    * TP = RF16[ T4 ]
///                                    ###
///               %unsigned 1  TPJ
///                                    ###
///                                    * TP = PC[15:0] + { 8'h00, L8[7:0] }
///                                    ###
///               %unsigned 1  TP4S
///                                    ###
///                                    * TP = { 12{T4[3]}, T4[3:0] }
///                                    ###
///               %unsigned 1  TP8L
///                                    ###
///                                    * TP = { 8'h00, I8[7:0] }
///                                    ###
///               %unsigned 1  TP8H
///                                    ###
///                                    * TP = { I8[7:0], 8'h00 }
///                                    ###
///               %unsigned 1  TP8LF
///                                    ###
///                                    * TP = { 8'hFF, I8[7:0] }
///                                    ###
///               %unsigned 1  TP8HF
///                                    ###
///                                    * TP = { I8[7:0], 8'hFF }
///                                    ###
///               %unsigned 1  SQRF64
///                                    ###
///                                    * SQL = RF64.out[63:0]
///                                    * SQH = RF64.out[127:64]
///                                    * ( 128b RF64.out is loaded by address of Q6[5:1] at ID stage )
///                                    ###
///               %unsigned 1  TQRF16Q
///                                    ###
///                                    * TQ = RF16@64[ X2 ]
///                                    ###
///               %unsigned 1  TQRFx4
///                                    ###
///                                    * TQ = 4{ RF16[ T4 ] }
///                                    ###
///               %unsigned 1  RD
///                                    ###
///                                    * Enable memory read from address { RA[15:3], 3'h0 }
///                                    ###
///               %unsigned 1  WARF
///                                    ###
///                                    * WA = RFSP[15:0]
///                                    ###
///               %unsigned 1  WAK8
///                                    ###
///                                    * WA = RFSP[15:0] + { 8{K8[7]}, K8[7:0] }
///                                    ###
///               %unsigned 1  WAK16
///                                    ###
///                                    * WA = K16[15:0]
///                                    ###
///               %%        10         # Stuffing bits...
///     @ 0x00010 EX                   (P)
///               ###
///               * Controls at EX stage (ALU16)
///               ###
///               %unsigned 1  ALU16FlagZ
///                                    ###
///                                    * Update flag-Z
///                                    ###
///               %unsigned 1  ALU16FlagC
///                                    ###
///                                    * Update flag-C
///                                    ###
///               %unsigned 1  ALU16FlagN
///                                    ###
///                                    * Update flag-N
///                                    ###
///               %unsigned 1  ALU16FlagV
///                                    ###
///                                    * Update flag-V
///                                    ###
///               %unsigned 1  ALU16FlagTP
///                                    ###
///                                    * { V, N, C, Z } = TP[3:0]
///                                    ###
///               %unsigned 1  ALU16MUL
///                                    ###
///                                    * { MDH, MDL } = SP * TP
///                                    * ( multi-stage operation )
///                                    ###
///               %unsigned 1  ALU16DIV
///                                    ###
///                                    * MDH = SP / TP
///                                    * MDL = SP % TP
///                                    * ( multi-stage operation )
///                                    ###
///               %unsigned 1  ALU16FlagLD
///                                    ###
///                                    * WB = Flag[15:0]
///                                    ###
///               %unsigned 1  ALU16MDL
///                                    ###
///                                    * WB = MDL[15:0]
///                                    ###
///               %unsigned 1  ALU16MDH
///                                    ###
///                                    * WB = MDH[15:0]
///                                    ###
///               %unsigned 1  ALU16ADD
///                                    ###
///                                    * WB = SP + TP
///                                    ###
///               %unsigned 1  ALU16SUB
///                                    ###
///                                    * WB = SP + ~TP + 1
///                                    ###
///               %unsigned 1  ALU16ADDC
///                                    ###
///                                    * WB = SP + TP + C
///                                    ###
///               %unsigned 1  ALU16SUBC
///                                    ###
///                                    * WB = SP + ~TP + (1 - C)
///                                    ###
///               %unsigned 1  ALU16ASR
///                                    ###
///                                    * WB = (signed) SP >> TP[3:0] or 16
///                                    ###
///               %unsigned 1  ALU16SL
///                                    ###
///                                    * WB = (unsigned) SP << TP[3:0] or 16
///                                    ###
///               %unsigned 1  ALU16SR
///                                    ###
///                                    * WB = (unsigned) SP >> TP[3:0] or 16
///                                    ###
///               %unsigned 1  ALU16GET
///                                    ###
///                                    * WB = GetBitField( SP, LSb = C4, Bits=T4 )
///                                    ###
///               %unsigned 1  ALU16SET
///                                    ###
///                                    * WB = SetBitField( SP, TP, LSb = C4, Bits=D4 )
///                                    ###
///               %unsigned 1  ALU16SEL
///                                    ###
///                                    * WB = Flag[ C4 ] ? SP : TP
///                                    ###
///               %unsigned 1  ALU16OR
///                                    ###
///                                    * WB = SP | TP
///                                    ###
///               %unsigned 1  ALU16AND
///                                    ###
///                                    * WB = SP & TP
///                                    ###
///               %unsigned 1  ALU16XOR
///                                    ###
///                                    * WB = SP ^ TP
///                                    ###
///               %unsigned 1  ALU16SP
///                                    ###
///                                    * WB = SP
///                                    ###
///               %%        8          # Stuffing bits...
///     @ 0x00014 EXX                  (P)
///               ###
///               * Controls at EX stage (others)
///               ###
///               %unsigned 1  WRSQ
///                                    ###
///                                    * Enable memory write of SQ to address WA
///                                    * M64[ WA[15:3] ] = Q6[0] ? SQH[63:0] : SQL[63:0]
///                                    ###
///               %unsigned 1  WR16
///                                    ###
///                                    * Enable partial memory write (16b) of TQ to address WA
///                                    * M64[ WA[15:3] ][ WA[2:1] ] = TQ[ WA[2:1] ]
///                                    ###
///               %unsigned 1  WRTQ
///                                    ###
///                                    * Enable memory write of TQ to address WA
///                                    * M64[ WA[15:3] ] = TQ[63:0]
///                                    ###
///               %unsigned 1  ALU64PUSH
///                                    ###
///                                    * Push a operation request to ALU64 with parameters:
///                                    * ALU64.CMD( K8[7:0], SP[15:0], TQ[63:0], SQ[127:0] )
///                                    ###
///               %unsigned 1  ALU64POP
///                                    ###
///                                    * Pop a result from ALU64 (stall if not ready):
///                                    * WB64 = ALU64.LD( S4[3:0] )
///                                    ###
///               %unsigned 1  ALU64SQ
///                                    ###
///                                    * WB64 = Q6[0] ? SQH[63:0] : SQL[63:0]
///                                    ###
///               %unsigned 1  ALU64TQ
///                                    ###
///                                    * WB64 = TQ[63:0]
///                                    ###
///               %unsigned 1  ALU64MEM
///                                    ###
///                                    * WB64 = M64.out
///                                    ###
///               %unsigned 1  BRANCH
///                                    ###
///                                    * if( PrevFlag[ C4 ] )
///                                    * BranchStack.Push( TP[15:0], SP[15:0] );
///                                    ###
///               %%        23         # Stuffing bits...
///     @ 0x00018 WB                   (P)
///               ###
///               * Controls at WB stage
///               ###
///               %unsigned 1  RF16
///                                    ###
///                                    * RF16[ W4 ] = WB
///                                    ###
///               %unsigned 1  RF16W0
///                                    ###
///                                    * RF16[ W4 ] = WB64[15:0]
///                                    ###
///               %unsigned 1  RF16MEM
///                                    ###
///                                    * RF16[ D4 ] = WB64[ RA[2:1] ]
///                                    ###
///               %unsigned 1  RF16Q
///                                    ###
///                                    * RF16@64[ X2 ] = WB64[63:0]
///                                    ###
///               %unsigned 1  RF64
///                                    ###
///                                    * RF64[ Q6 ] = WB64[63:0]
///                                    ###
///               %%        27         # Stuffing bits...
///     # # ----------------------------------------------------------
/// $ENDOFINTERFACE  # size:      28B, bits:     116b, padding:     0B
////////////////////////////////////////////////////////////
