///               %unsigned 1  RF16
///               %unsigned 1  RF16W0
///               %unsigned 1  RF16MEM
///               %unsigned 1  RF16Q                     0x1
///               %unsigned 1  RF64
///               %%        27         # Stuffing bits...
///     # # ----------------------------------------------------------
/// $ENDOFINTERFACE  # size:      28B, bits:     116b, padding:     0B
