///               %unsigned 1  WRSQ
///               %unsigned 1  WR16                      0x1
///               %unsigned 1  WRTQ
///               %unsigned 1  ALU64PUSH
///               %unsigned 1  ALU64POP
///               %unsigned 1  ALU64SQ
