//////
///
/// $INTERFACE ISA_XWRINC                               (4,4)
///     ###
///     * Memory write of 64b quad-register.
///     * Using a register load write address.
///     * This address register will be updated with an offset of [-128~127] afterwards, no flags are affected.
///     ###
///     # # ----------------------------------------------------------
///     @ 0x00000 Mask                 (P)
///               %unsigned 24 INS                       0xF0000F
///               %%        8          # Stuffing bits...
///     @ 0x00004 Opcode               (P)
///               %unsigned 24 INS                       0x50000D
///                                    ###
///                                    * -
///                                    * - { "X.WR.INC", "rS,N,xT"     , "0101 NNNN SSSS NNNN TT-- 1101" } ,
///                                    * - Usage:
///                                    * -    X.WR.INC %a1, + 8, %x2   ; M64[ %a1 ] = %x2;
///                                    * -                             ; %a1 += 8;
///                                    ###
///               %%        8          # Stuffing bits...
///     @ 0x00008 ID                   (P)
///               ###
///               * Controls at ID stage
///               ###
///               %unsigned 1  RBRF
///               %unsigned 1  RARF
///               %unsigned 1  RAK8
///               %unsigned 1  RAI16
///               %unsigned 1  RAK16
///               %unsigned 1  RFSP                      0x1
///               %unsigned 1  W4D4
///               %unsigned 1  W4S4                      0x1
///               %%        24         # Stuffing bits...
///     @ 0x0000C LD                   (P)
///               ###
///               * Controls at LD stage
///               ###
///               %unsigned 1  SPRF
///               %unsigned 1  SPK8                      0x1
///               %unsigned 1  SPJ
///               %unsigned 1  SP4S
///               %unsigned 1  SP8S
///               %unsigned 1  SP8U
///               %unsigned 1  SP12S
///               %unsigned 1  SP16
///               %unsigned 1  TPRF
///               %unsigned 1  TPJ
///               %unsigned 1  TP4S
///               %unsigned 1  TP8L
///               %unsigned 1  TP8H
///               %unsigned 1  TP8LF
///               %unsigned 1  TP8HF
///               %unsigned 1  SQRF64
///               %unsigned 1  TQRF16Q                   0x1
///               %unsigned 1  TQRFx4
///               %unsigned 1  RD
///               %unsigned 1  WARF                      0x1
///               %unsigned 1  WAK8
///               %unsigned 1  WAK16
///               %%        10         # Stuffing bits...
///     @ 0x00010 EX                   (P)
///               ###
///               * Controls at EX stage (ALU16)
///               ###
///               %unsigned 1  ALU16FlagZ
///               %unsigned 1  ALU16FlagC
///               %unsigned 1  ALU16FlagN
///               %unsigned 1  ALU16FlagV
///               %unsigned 1  ALU16FlagTP
///               %unsigned 1  ALU16MUL
///               %unsigned 1  ALU16DIV
///               %unsigned 1  ALU16FlagLD
///               %unsigned 1  ALU16MDL
///               %unsigned 1  ALU16MDH
///               %unsigned 1  ALU16ADD
///               %unsigned 1  ALU16SUB
///               %unsigned 1  ALU16ADDC
///               %unsigned 1  ALU16SUBC
///               %unsigned 1  ALU16ASR
///               %unsigned 1  ALU16SL
///               %unsigned 1  ALU16SR
///               %unsigned 1  ALU16GET
///               %unsigned 1  ALU16SET
///               %unsigned 1  ALU16SEL
///               %unsigned 1  ALU16OR
///               %unsigned 1  ALU16AND
///               %unsigned 1  ALU16XOR
///               %unsigned 1  ALU16SP                   0x1
///               %%        8          # Stuffing bits...
///     @ 0x00014 EXX                  (P)
///               ###
///               * Controls at EX stage (others)
///               ###
///               %unsigned 1  WRSQ
///               %unsigned 1  WR16
///               %unsigned 1  WRTQ                      0x1
///               %unsigned 1  ALU64PUSH
