///               %unsigned 1  TPJ
///               %unsigned 1  TP4S
///               %unsigned 1  TP8L
///               %unsigned 1  TP8H
///               %unsigned 1  TP8LF
///               %unsigned 1  TP8HF
///               %unsigned 1  SQRF64                    0x1
///               %unsigned 1  TQRF16Q
///               %unsigned 1  TQRFx4
///               %unsigned 1  RD
///               %unsigned 1  WARF
///               %unsigned 1  WAK8                      0x1
///               %unsigned 1  WAK16
///               %%        10         # Stuffing bits...
