///               %unsigned 1  ALU16SEL
///               %unsigned 1  ALU16OR
///               %unsigned 1  ALU16AND
///               %unsigned 1  ALU16XOR
///               %unsigned 1  ALU16SP
///               %%        8          # Stuffing bits...
///     @ 0x00014 EXX                  (P)
///               ###
///               * Controls at EX stage (others)
///               ###
///               %unsigned 1  WRSQ
///               %unsigned 1  WR16
///               %unsigned 1  WRTQ
///               %unsigned 1  ALU64PUSH
///               %unsigned 1  ALU64POP
///               %unsigned 1  ALU64SQ
///               %unsigned 1  ALU64TQ
///               %unsigned 1  ALU64MEM
