/// $INTERFACE ISA_ADD                                  (4,4)
///     ###
///     * Add 2 registers to another register.
///     * All flags 'ZCNV' will be updated.
///     ###
///     # # ----------------------------------------------------------
///     @ 0x00000 Mask                 (P)
///               %unsigned 24 INS                       0xFF0000
///               %%        8          # Stuffing bits...
///     @ 0x00004 Opcode               (P)
///               %unsigned 24 INS                       0x100000
///                                    ###
///                                    * -
///                                    * - { "ADD"     , "rD,rS,rT"    , "0001 0000 SSSS ---- TTTT DDDD" } ,
///                                    * - Usage:
///                                    * -    ADD      %d1, %b1, %a1    ; %d1 = %b1 + %a1;
///                                    ###
///               %%        8          # Stuffing bits...
///     @ 0x00008 ID                   (P)
///               ###
///               * Controls at ID stage
///               ###
///               %unsigned 1  RBRF
///               %unsigned 1  RARF
///               %unsigned 1  RAK8
///               %unsigned 1  RAI16
///               %unsigned 1  RAK16
///               %unsigned 1  RFSP                      0x1
///               %unsigned 1  W4D4                      0x1
///               %unsigned 1  W4S4
///               %%        24         # Stuffing bits...
///     @ 0x0000C LD                   (P)
///               ###
///               * Controls at LD stage
///               ###
///               %unsigned 1  SPRF                      0x1
///               %unsigned 1  SPK8
///               %unsigned 1  SPJ
///               %unsigned 1  SP4S
///               %unsigned 1  SP8S
///               %unsigned 1  SP8U
///               %unsigned 1  SP12S
///               %unsigned 1  SP16
///               %unsigned 1  TPRF                      0x1
///               %unsigned 1  TPJ
///               %unsigned 1  TP4S
///               %unsigned 1  TP8L
///               %unsigned 1  TP8H
///               %unsigned 1  TP8LF
///               %unsigned 1  TP8HF
///               %unsigned 1  SQRF64
///               %unsigned 1  TQRF16Q
///               %unsigned 1  TQRFx4
///               %unsigned 1  RD
///               %unsigned 1  WARF
///               %unsigned 1  WAK8
///               %unsigned 1  WAK16
///               %%        10         # Stuffing bits...
///     @ 0x00010 EX                   (P)
///               ###
///               * Controls at EX stage (ALU16)
///               ###
///               %unsigned 1  ALU16FlagZ                0x1
///               %unsigned 1  ALU16FlagC                0x1
///               %unsigned 1  ALU16FlagN                0x1
///               %unsigned 1  ALU16FlagV                0x1
///               %unsigned 1  ALU16FlagTP
///               %unsigned 1  ALU16MUL
///               %unsigned 1  ALU16DIV
///               %unsigned 1  ALU16FlagLD
///               %unsigned 1  ALU16MDL
///               %unsigned 1  ALU16MDH
///               %unsigned 1  ALU16ADD                  0x1
///               %unsigned 1  ALU16SUB
///               %unsigned 1  ALU16ADDC
///               %unsigned 1  ALU16SUBC
///               %unsigned 1  ALU16ASR
///               %unsigned 1  ALU16SL
///               %unsigned 1  ALU16SR
///               %unsigned 1  ALU16GET
///               %unsigned 1  ALU16SET
///               %unsigned 1  ALU16SEL
///               %unsigned 1  ALU16OR
///               %unsigned 1  ALU16AND
///               %unsigned 1  ALU16XOR
///               %unsigned 1  ALU16SP
///               %%        8          # Stuffing bits...
///     @ 0x00014 EXX                  (P)
///               ###
///               * Controls at EX stage (others)
///               ###
///               %unsigned 1  WRSQ
///               %unsigned 1  WR16
///               %unsigned 1  WRTQ
///               %unsigned 1  ALU64PUSH
///               %unsigned 1  ALU64POP
///               %unsigned 1  ALU64SQ
///               %unsigned 1  ALU64TQ
///               %unsigned 1  ALU64MEM
///               %unsigned 1  BRANCH
///               %%        23         # Stuffing bits...
